content:
.page { padding: 24px; min-width: 0; }
.header { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-bottom: 24px; }
.header > div { min-width: 0; }
.addButton { min-height: 44px; flex-shrink: 0; justify-content: center; }
.stats { gap: 12px; }
.filters { display: grid; grid-template-columns: minmax(0, 1fr) minmax(180px, .4fr); gap: 12px; margin-bottom: 20px; }
.filters > * { width: 100%; min-width: 0; min-height: 44px; }
.formFields { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.card { padding: 20px; }
.cardLayout { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: start; gap: 24px; }
.content { min-width: 0; overflow-wrap: anywhere; }
.question { font-size: 15px; line-height: 1.5; margin-bottom: 8px; }
.answer { font-size: 14px; line-height: 1.75; white-space: pre-line; }
.actions { display: flex; align-items: center; gap: 8px; }
.actions > button { min-height: 44px; }
.toggle { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-width: 44px; min-height: 44px; padding: 0; border: 0; background: transparent; cursor: pointer; flex-shrink: 0; border-radius: 8px; }
.track { position: relative; display: block; flex: 0 0 36px; width: 36px; height: 20px; border-radius: 20px; background: #d4d4d4; transition: background .15s; }
.track[data-active="true"] { background: #059669; }
.thumb { position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: white; box-shadow: 0 1px 3px #0002; transition: transform .15s; }
.track[data-active="true"] .thumb { transform: translateX(16px); }
.status { display: none; font-size: 12px; font-weight: 600; color: #52645a; }
@media (max-width: 767px) {
  .page { padding: 0; }
  .header { flex-direction: column; align-items: stretch; gap: 14px; margin-bottom: 20px; }
  .addButton { width: 100%; }
  .stats { gap: 8px; margin-bottom: 18px; }
  .stats > button { padding: 12px 4px; min-width: 0; }
  .stats > button > p:last-child { font-size: 9px; letter-spacing: .04em; }
  .filters { grid-template-columns: minmax(0, 1fr); gap: 10px; margin-bottom: 16px; }
  .filters > * { font-size: 16px; min-height: 48px; border-radius: 12px; }
  .card { padding: 18px 16px 8px; }
  .cardLayout { grid-template-columns: minmax(0, 1fr); gap: 16px; }
  .question { font-size: 16px; line-height: 1.5; }
  .answer { font-size: 14px; line-height: 1.75; }
  .actions { border-top: 1px solid #edf0ed; padding-top: 8px; display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 8px; }
  .actions > button { min-height: 44px; font-size: 12px; padding-inline: 12px; }
  .actions > .toggle { justify-content: flex-start; padding: 0; }
  .status { display: inline; }
  .formFields { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 359px) {
  .actions { gap: 6px; }
  .actions > button { padding-inline: 9px; font-size: 11px; }
  .status { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .track, .thumb { transition: none; }
}
